create table if not exists visions ( id uuid primary key default gen_random_uuid(), user_id uuid, statement text not null, target_year int, created_at timestamptz not null default now() ); alter table visions enable row level security; drop policy if exists "visions_v1_read" on visions; create policy "visions_v1_read" on visions for select using (true); drop policy if exists "visions_v1_write" on visions; create policy "visions_v1_write" on visions for all using (true) with check (true); create table if not exists domains ( id uuid primary key default gen_random_uuid(), user_id uuid, name text not null, slug text not null, created_at timestamptz not null default now() ); alter table domains enable row level security; drop policy if exists "domains_v1_read" on domains; create policy "domains_v1_read" on domains for select using (true); drop policy if exists "domains_v1_write" on domains; create policy "domains_v1_write" on domains for all using (true) with check (true); create table if not exists goals ( id uuid primary key default gen_random_uuid(), user_id uuid, vision_id uuid references visions(id) on delete set null, domain_id uuid references domains(id) on delete set null, title text not null, description text, term text not null default 'short', status text not null default 'active', target_date date, created_at timestamptz not null default now() ); alter table goals enable row level security; drop policy if exists "goals_v1_read" on goals; create policy "goals_v1_read" on goals for select using (true); drop policy if exists "goals_v1_write" on goals; create policy "goals_v1_write" on goals for all using (true) with check (true); create table if not exists activities ( id uuid primary key default gen_random_uuid(), user_id uuid, goal_id uuid references goals(id) on delete cascade, activity_type text not null, duration_minutes int default 0, value numeric default 0, notes text, activity_date date not null default current_date, created_at timestamptz not null default now() ); alter table activities enable row level security; drop policy if exists "activities_v1_read" on activities; create policy "activities_v1_read" on activities for select using (true); drop policy if exists "activities_v1_write" on activities; create policy "activities_v1_write" on activities for all using (true) with check (true); create table if not exists weekly_scorecards ( id uuid primary key default gen_random_uuid(), user_id uuid, week_start date not null, week_end date not null, composite_score numeric not null default 0, domain_scores jsonb not null default '{}', activity_count int not null default 0, previous_score numeric, trend text, ai_summary text, ai_source text, ai_confidence numeric, review_status text default 'unreviewed', created_at timestamptz not null default now() ); alter table weekly_scorecards enable row level security; drop policy if exists "weekly_scorecards_v1_read" on weekly_scorecards; create policy "weekly_scorecards_v1_read" on weekly_scorecards for select using (true); drop policy if exists "weekly_scorecards_v1_write" on weekly_scorecards; create policy "weekly_scorecards_v1_write" on weekly_scorecards for all using (true) with check (true); insert into visions (id, user_id, statement, target_year) values ('a0000000-0000-0000-0000-000000000001', null, 'Become a world-class educator and build a platform that teaches 100,000 students exponential growth principles by 2035.', 2035) on conflict (id) do nothing; insert into domains (id, user_id, name, slug) values ('d0000000-0000-0000-0000-000000000001', null, 'Health', 'health'), ('d0000000-0000-0000-0000-000000000002', null, 'Soft Skill', 'soft-skill'), ('d0000000-0000-0000-0000-000000000003', null, 'Education', 'education'), ('d0000000-0000-0000-0000-000000000004', null, 'Other', 'other') on conflict (id) do nothing; insert into goals (id, user_id, vision_id, domain_id, title, description, term, status, target_date) values ('g0000000-0000-0000-0000-000000000001', null, 'a000